/* Load only the necessary families and weights, or self-host with valid licenses. */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600&family=Space+Grotesk:wght@500;600;700&display=swap');
:root {
  --color-bg: #F0EEE9;
  --color-surface: #FFFFFF;
  --color-text: #1D2928;
  --color-brand: #1F5F5B;
  --color-brand-ink: #FFFFFF;
  --color-border: #B8CCC8;
  --font-display: 'Space Grotesk', 'Arial', sans-serif;
  --font-body: 'Inter', 'Arial', sans-serif;
  --radius-md: 14px;
}
body { background: var(--color-bg); color: var(--color-text); font-family: var(--font-body); line-height: 1.55; }
h1, h2, h3 { font-family: var(--font-display); letter-spacing: -0.035em; }
h1 { font-weight: 700; font-size: clamp(2.6rem,5vw,5.5rem); line-height: 1.05; }
h2 { font-size: clamp(1.7rem,3vw,3.1rem); line-height: 1.1; }
.btn-primary { background: var(--color-brand); color: var(--color-brand-ink); font: 600 1rem var(--font-body); padding: 0.85rem 1.25rem; border-radius: 999px; }
.btn-primary:hover { filter: brightness(.92); }
.btn-primary:focus-visible { outline: 3px solid #14213D; outline-offset: 3px; }

@import url('https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600&family=Space+Grotesk:wght@600;700&display=swap');
:root {
  --background: #F0EDE4;
  --foreground: #004741;
  --surface: #FFFFFF;
  --primary: #004741;
  --primary-foreground: #F0EDE4;
  --accent: #004741; /* P13 uses its own green for actions; avoid accidental palette mixing */
  --border: #B6CAC4;
  --font-display: 'Space Grotesk', Arial, sans-serif;
  --font-body: 'Manrope', Arial, sans-serif;
}
body { background: var(--background); color: var(--foreground); font-family: var(--font-body); line-height: 1.55; }
h1, h2, h3 { font-family: var(--font-display); letter-spacing: -.025em; }
h1 { font-size: clamp(2.4rem, 5vw, 5.2rem); line-height: 1.04; }
button, input, textarea { font: inherit; }
a:focus-visible, button:focus-visible { outline: 3px solid var(--foreground); outline-offset: 3px; }
@media (max-width: 640px) { .hero-grid { display: grid; grid-template-columns: 1fr; gap: 1.5rem; } }
